269		timeoutMs: number,
270		signal?: AbortSignal,
271	): Promise<unknown> {
272		const read = Effect.callback<unknown, HttpRequestError>(
273			(resume, interruptionSignal) => {
274				let size = 0;
275				const chunks: Buffer[] = [];
276				let settled = false;
277				const handlers: ReadBodyHandlers = {
278					onData: () => {},
279					onError: () => {},
280					onAbort: () => {},
281					onEnd: () => {},
282					onTimeout: () => {},
283				};
284				const cleanup = () => {
285					request.removeListener("data", handlers.onData);
286					request.removeListener("end", handlers.onEnd);
287					request.removeListener("error", handlers.onError);
288					signal?.removeEventListener("abort", handlers.onAbort);
289					interruptionSignal.removeEventListener("abort", handlers.onAbort);
290				};
291				const settle = (
292					effect:
293						| ReturnType<typeof Effect.succeed<unknown>>
294						| ReturnType<typeof Effect.fail<HttpRequestError>>,
295				) => {
296					if (settled) return;
297					settled = true;
298					cleanup();
299					resume(effect);
300				};
301				const rejectAndDrain = (error: HttpRequestError) => {
302					if (settled) return;
303					settled = true;
304					cleanup();
305					request.resume();
306					resume(Effect.fail(error));
307				};
308				handlers.onData = (chunk: Buffer | string) => {
309					const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
310					size += buffer.byteLength;
311					if (size > MAX_BODY_BYTES) {
312						rejectAndDrain(
313							new HttpRequestError(413, "Request body is too large."),
314						);
315						return;
316					}
317					if (!settled) chunks.push(buffer);
318				};
319				handlers.onError = (_error: Error) =>
320					settle(
321						Effect.fail(
322							new HttpRequestError(500, "Request body could not be read."),
323						),
324					);
325				handlers.onAbort = () =>
326					rejectAndDrain(
327						new HttpRequestError(
328							503,
329							"HTTP server is shutting down. Retry shortly.",
330						),
331					);
332				handlers.onEnd = () => {
333					try {
334						const raw = Buffer.concat(chunks).toString("utf8");
335						settle(
336							Effect.succeed(raw.length === 0 ? undefined : JSON.parse(raw)),
337						);
338					} catch {
339						settle(
340							Effect.fail(
341								new HttpRequestError(400, "Request body must be valid JSON."),
342							),
343						);
344					}
345				};
346				handlers.onTimeout = () =>
347					rejectAndDrain(new HttpRequestError(408, "Request body timed out."));
