385	function closeServer(server: Server): Promise<void> {
386		return new Promise((resolve, reject) => {
387			if (!server.listening) {
388				resolve();
389				return;
390			}
391			setTimeout(() => {
392				server.close((error) => (error ? reject(error) : resolve()));
393				// Let the current request turn write a bounded shutdown response
394				// before closing connections. Closing idle or active connections in
395				// the same turn as `shuttingDown = true` can reset a request admitted
396				// just before close() before its 503 reaches the client.
397				setTimeout(() => {
398					server.closeIdleConnections();
399					server.closeAllConnections();
400				}, 20).unref?.();
401			}, 20).unref?.();
402		});
403	}
