405	function isBearerAuthorized(
406		request: IncomingMessage,
407		token: string | undefined,
408	): boolean {
409		if (!token) return false;
410		const header = request.headers.authorization;
411		if (!isString(header)) return false;
412		const expected = Buffer.from(`Bearer ${token}`);
413		const actual = Buffer.from(header);
414		return (
415			expected.byteLength === actual.byteLength &&
416			timingSafeEqual(expected, actual)
417		);
418	}
