443	function drainRequestBody(request: IncomingMessage, timeoutMs: number): void {
444		const cleanup = () => {
445			clearTimeout(timer);
446			request.removeListener("end", cleanup);
447			request.removeListener("error", cleanup);
448			request.removeListener("close", cleanup);
449		};
450		const timer = setTimeout(() => request.destroy(), timeoutMs);
451		request.once("end", cleanup);
452		request.once("error", cleanup);
453		request.once("close", cleanup);
454		timer.unref?.();
455		request.resume();
456	}
