530		function armIdleEviction(session: HttpSession): void {
531			if (session.closed) return;
532			session.idleGeneration += 1;
533			const generation = session.idleGeneration;
534			if (session.idleFiber) {
535				Effect.runFork(Fiber.interrupt(session.idleFiber));
536			}
537			const idle = Effect.sleep(Duration.millis(config.idleTimeoutMs)).pipe(
538				Effect.andThen(
539					Effect.sync(() => {
540						if (session.closed || session.idleGeneration !== generation) {
541							return;
542						}
543						const hasActiveResponse = [...session.responses].some(
544							(response) => !response.writableEnded,
545						);
546						if (hasActiveResponse) {
547							queueMicrotask(() => armIdleEviction(session));
548							return;
549						}
550						recordHttpSessionEviction();
551						queueMicrotask(() => {
552							void closeSession(session).catch((error) => {
553								cleanupErrors.push(error);
554							});
555						});
556					}),
557				),
558			);
559			session.idleFiber = Effect.runSync(
560				Effect.forkIn(idle, session.scope, { startImmediately: true }),

content.content:
 560				Effect.forkIn(idle, session.scope, { startImmediately: true }),
 561			);
 562		}
