 564		async function closeSession(
 565			session: HttpSession,
 566			failureCategory?: "connect_failure" | "startup_failure" | "unknown",
 567		): Promise<void> {
 568			if (failureCategory && !session.terminationCategory) {
 569				session.terminationCategory = failureCategory;
 570			}
 571			if (session.closePromise) return session.closePromise;
 572			session.closed = true;
 573			session.closePromise = (async () => {
 574				// The registry only indexes sessions. Ownership and cleanup live in
 575				// the child Scope finalizer below.
 576				await Effect.runPromise(Scope.close(session.scope, Exit.void));
 577				if (session.finalizationErrors.length > 0) {
 578					throw aggregateErrors(
 579						session.finalizationErrors,
 580						"MCP session cleanup failed.",
 581					);
 582				}
 583			})();
 584			return session.closePromise;
 585		}
