 587		function trackSessionResponse(
 588			session: HttpSession,
 589			response: ServerResponse,
 590		): void {
 591			session.responses.add(response);
 592			response.once("close", () => {
 593				session.responses.delete(response);
 594				// A destroyed response means the client disconnected before the
 595				// exchange completed. The SDK does not expose a request-scoped signal
 596				// for this transport, so evict and close the whole session rather than
 597				// leaving an aborted session reusable or poisoning future requests.
 598				if (!response.writableEnded && !session.closed) {
 599					void closeSession(session).catch((error) => {
 600						cleanupErrors.push(error);
 601					});
 602				} else if (!session.closed) {
 603					armIdleEviction(session);
 604				}
 605			});
 606		}
