 734		async function handleInitializedSession<T>(
 735			request: IncomingMessage,
 736			response: ServerResponse,
 737			body: T,
 738			reservation: InitializationReservation,
 739		): Promise<void> {
 740			const context = createMcpSessionContext(isObject(body) ? body : {}, "http");
 741			recordMcpSessionStart(isObject(body) ? body : {}, "http", context);
 742			let session: HttpSession | undefined;
 743			let mcpServer: OwnedMcpServer | undefined;
 744			let connected = false;
 745			const lifecycleController = reservation.controller;
 746			const transport = new NodeStreamableHTTPServerTransport({
 747				sessionIdGenerator: randomUUID,
 748				onsessioninitialized: (id) => {
 749					if (!session) return;
 750					if (shuttingDown || lifecycleController.signal.aborted) {
 751						void closeSession(session, "startup_failure").catch((error) => {
 752							cleanupErrors.push(error);
 753						});
 754						return;
 755					}
 756					session.id = id;
 757					sessions.set(id, session);
 758					pendingSessions.delete(session);
 759					initializationControllers.delete(lifecycleController);
 760					armIdleEviction(session);
 761				},
 762			});
 763			transport.onclose = () => {
 764				if (session) {
 765					void closeSession(session).catch((error) => {
 766						cleanupErrors.push(error);
 767					});
 768				}
 769			};
 770			try {
 771				const scope = await Effect.runPromise(Scope.fork(httpScope));
 772				session = {
 773					transport,
 774					context,
 775					lifecycleController,
 776					scope,
 777					responses: new Set(),
 778					idleGeneration: 0,
 779					finalizationErrors: [],
 780					terminationRecorded: false,
 781					closed: false,
 782				};
 783				// Initialization is owned by the server scope from the moment its
 784				// child scope exists, not only after the SDK assigns a session id.
 785				pendingSessions.add(session);
 786				await Effect.runPromise(
 787					Scope.addFinalizer(
 788						scope,
 789						Effect.promise(async () => {
 790							const currentSession = session;
 791							if (!currentSession) return;
 792							pendingSessions.delete(currentSession);
 793							if (currentSession.id) sessions.delete(currentSession.id);
 794							currentSession.lifecycleController.abort(
 795								new DOMException("MCP session closed", "AbortError"),
 796							);
 797							for (const response of currentSession.responses) {
 798								if (!response.writableEnded) response.destroy();
 799							}
 800							const results = await Promise.allSettled([
 801								Promise.resolve().then(() => currentSession.transport.close()),
 802								...(currentSession.server
 803									? [Promise.resolve().then(() => currentSession.server?.close())]
 804									: []),
 805							]);
 806							currentSession.finalizationErrors.push(
 807								...results.flatMap((result) =>
 808									result.status === "rejected" ? [result.reason] : [],
 809								),
 810							);
 811							if (!currentSession.terminationRecorded) {
 812								currentSession.terminationRecorded = true;
 813								const succeeded = currentSession.finalizationErrors.length === 0;
 814								recordMcpSessionTermination(
 815									currentSession.terminationCategory && succeeded
 816										? currentSession.terminationCategory
 817										: resolveSessionTerminationCategory(
 818												succeeded,
 819												currentSession.context,
 820											),
 821									currentSession.context,
 822								);
 823							}
 824						}),
 825					),
 826				);
 827				mcpServer = await createMcpServer({
 828					apiKey,
 829					lifecycleSignal: lifecycleController.signal,
 830				});
 831				const currentSession = session;
 832				if (!currentSession) {
 833					await mcpServer.close();
 834					return;
 835				}
 836				if (currentSession.closed) {
 837					await mcpServer.close().catch((error) => {
 838						currentSession.finalizationErrors.push(error);
 839					});
 840					return;
 841				}
 842				if (shuttingDown || lifecycleController.signal.aborted) {
 843					currentSession.server = mcpServer;
 844					await closeSession(currentSession, "startup_failure");
 845					return;
 846				}
 847				currentSession.server = mcpServer;
 848				await mcpServer.connect(transport);
 849				connected = true;
 850				if (shuttingDown || lifecycleController.signal.aborted) {
 851					await closeSession(currentSession, "startup_failure");
 852					return;
 853				}
 854				trackSessionResponse(currentSession, response);
 855				await runWithMcpSessionContext(context, () =>
 856					transport.handleRequest(request, response, body),
 857				);
 858			} catch (error) {
 859				lifecycleController.abort(
 860					new DOMException("MCP session startup failed", "AbortError"),
 861				);
 862				console.error(`HTTP session request failed: ${safeDiagnostic(error)}`);
 863				let cleanupError: unknown;
 864				try {
 865					if (session) {
 866						await closeSession(
 867							session,
 868							connected ? "unknown" : "connect_failure",
 869						);
 870					} else {
 871						const ownedServer = mcpServer;
 872						const results = await Promise.allSettled([
 873							Promise.resolve().then(() => transport.close()),
 874							...(ownedServer
 875								? [Promise.resolve().then(() => ownedServer.close())]
 876								: []),
 877						]);
 878						const errors = results.flatMap((result) =>
 879							result.status === "rejected" ? [result.reason] : [],
 880						);
 881						if (errors.length > 0) {
 882							throw aggregateErrors(errors, "MCP cleanup failed.");
 883						}
 884						recordMcpSessionTermination("startup_failure", context);
 885					}
 886				} catch (cleanupFailure) {
 887					cleanupError = cleanupFailure;
 888					if (!session) {
 889						recordMcpSessionTermination("startup_failure", context);
 890					}
 891				}
 892				if (cleanupError) {
 893					console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
 894				}
 895				if (!response.writableEnded && !shuttingDown)
 896					writeExecutionJson(response, 500, "Internal server error.", error);
 897			}
 898		}
