 909				writeJson(
 910					response,
 911					400,
 912					"Initialization must not include Mcp-Session-Id.",
 913				);
 914				return true;
 915			}
 916			if (!reservation) {
 917				writeJson(
 918					response,
 919					503,
 920					"MCP initialization capacity is unavailable. Retry shortly.",
 921				);
 922				return true;
 923			}
 924			await handleInitializedSession(request, response, body, reservation);
