 928		async function handleExistingSessionRequest<T>(
 929			request: IncomingMessage,
 930			response: ServerResponse,
 931			body: T,
 932			sessionId: string | undefined,
 933			existingSession: HttpSession | undefined,
 934			trackedExistingResponse: boolean,
 935		): Promise<void> {
