 941			if (!session) {
 942				writeJson(response, 404, "Unknown Mcp-Session-Id.");
 943				return;
 944			}
 945			armIdleEviction(session);
 946			if (request.method !== "DELETE" && !trackedExistingResponse) {
 947				trackSessionResponse(session, response);
 948			}
 949			await runWithMcpSessionContext(session.context, () =>
 950				session.transport.handleRequest(request, response, body),
 951			);
 952			if (request.method === "DELETE" && !session.closed) {
 953				try {
 954					await closeSession(session);
 955				} catch (error) {
 956					cleanupErrors.push(error);
 957				}
 958			}
 959		}
