 961		async function handleRequest(
 962			request: IncomingMessage,
 963			response: ServerResponse,
 964		): Promise<void> {
 965			let releaseInitialization: (() => void) | undefined;
 966			try {
 967				if (request.url?.split("?", 1)[0] === HEALTH_PATH) {
 968					drainRequestBody(request, config.bodyTimeoutMs);
 969					if (response.headersSent || response.destroyed) return;
 970					if (
 971						!validateHostHeader(
 972							request,
 973							hostNamesFor(options),
 974							listeningPort,
 975							wildcard,
 976						)
 977					) {
 978						writeJson(response, 403, "Invalid Host header");
 979						return;
 980					}
 981					if (request.method !== "GET") {
 982						response.setHeader("Allow", "GET");
 983						writeJson(response, 405, "Method not allowed");
 984						return;
 985					}
 986					response.statusCode = shuttingDown ? 503 : 200;
 987					response.setHeader("Content-Type", "application/json");
 988					response.setHeader("Cache-Control", "no-store");
 989					response.end(
 990						JSON.stringify({ status: shuttingDown ? "shutting_down" : "ok" }),
 991					);
 992					return;
 993				}
 994				const resolution = resolveRequestSession(request, response);
 995				if (!resolution) return;
 996				const requiresInitialization =
 997					request.method === "POST" && !resolution.sessionId;
 998				const reservation = requiresInitialization
 999					? reserveInitialization(request, response)
1000					: undefined;
1001				if (requiresInitialization && !reservation) return;
1002				releaseInitialization = reservation?.release;
1003				const body =
1004					request.method === "POST"
1005						? await readBody(
1006								request,
1007								config.bodyTimeoutMs,
1008								reservation?.controller.signal ??
1009									resolution.existingSession?.lifecycleController.signal,
1010							)
1011						: undefined;
1012				if (shuttingDown) {
1013					writeJson(
1014						response,
1015						503,
1016						"HTTP server is shutting down. Retry shortly.",
1017					);
1018					return;
1019				}
1020				if (
1021					await handleInitializationRequest(
1022						request,
1023						response,
1024						body,
1025						resolution.sessionId,
1026						reservation ?? undefined,
1027					)
1028				)
