 614		function resolveRequestSession(
 615			request: IncomingMessage,
 616			response: ServerResponse,
 617		): RequestSessionResolution | undefined {
 618			if (request.url?.split("?", 1)[0] !== MCP_PATH) {
 619				writeJson(response, 404, "Not found");
 620				return undefined;
 621			}
 622			if (
 623				!validateHostHeader(
 624					request,
 625					hostNamesFor(options),
 626					listeningPort,
 627					wildcard,
 628				)
 629			) {
 630				writeJson(response, 403, "Invalid Host header");
 631				return undefined;
 632			}
 633			if (!loopback && !isBearerAuthorized(request, bearerToken)) {
 634				writeJson(response, 401, "Authorization required");
 635				return undefined;
 636			}
 637	
 638			const sessionHeader = request.headers["mcp-session-id"];
 639			const sessionId = isString(sessionHeader) ? sessionHeader : undefined;
 640			const existingSession = sessionId ? sessions.get(sessionId) : undefined;
 641			if (sessionId && !existingSession) {
 642				rejectBeforeBody(
 643					request,
 644					response,
 645					404,
 646					"Unknown Mcp-Session-Id.",
 647					config.bodyTimeoutMs,
 648				);
 649				return undefined;
 650			}
 651			if (existingSession && request.method !== "DELETE") {
 652				trackSessionResponse(existingSession, response);
 653				return { sessionId, existingSession, trackedExistingResponse: true };
 654			}
 655			return { sessionId, existingSession, trackedExistingResponse: false };
 656		}
