 663		function reserveInitialization(
 664			request: IncomingMessage,
 665			response: ServerResponse,
 666		): InitializationReservation | null {
 667			if (shuttingDown) {
 668				recordHttpAdmissionRejection("shutting_down");
 669				rejectBeforeBody(
 670					request,
 671					response,
 672					503,
 673					"HTTP server is shutting down. Retry shortly.",
 674					config.bodyTimeoutMs,
 675				);
 676				return null;
 677			}
 678			if (sessions.size + initializationControllers.size >= config.maxSessions) {
 679				recordHttpAdmissionRejection("session_capacity");
 680				rejectBeforeBody(
 681					request,
 682					response,
 683					429,
 684					"MCP session capacity reached. Retry after an existing session closes.",
 685					config.bodyTimeoutMs,
 686				);
 687				return null;
 688			}
 689	
 690			const permitAcquired = Effect.runSync(
 691				initializingSemaphore.takeIfAvailable(1),
 692			);
 693			if (!permitAcquired) {
 694				recordHttpAdmissionRejection("initializing_capacity");
 695				rejectBeforeBody(
 696					request,
 697					response,
 698					503,
 699					"MCP server is busy initializing sessions. Retry shortly.",
 700					config.bodyTimeoutMs,
 701				);
 702				return null;
 703			}
 704			const controller = new AbortController();
 705			initializationControllers.add(controller);
 706			let resolveInitialization!: () => void;
 707			const initializationComplete = new Promise<void>((resolve) => {
 708				resolveInitialization = resolve;
 709			});
 710			initializationPromises.add(initializationComplete);
 711			let released = false;
 712			const onResponseClose = () => {
 713				if (!response.writableEnded) {
 714					controller.abort(
 715						new DOMException("MCP initialization response closed", "AbortError"),
 716					);
 717				}
 718			};
 719			response.once("close", onResponseClose);
 720			return {
 721				controller,
 722				release: () => {
 723					if (released) return;
 724					released = true;
 725					response.removeListener("close", onResponseClose);
 726					initializationControllers.delete(controller);
 727					initializationPromises.delete(initializationComplete);
 728					Effect.runSync(initializingSemaphore.release(1));
 729					resolveInitialization();
 730				},
 731			};
 732		}
