 900		async function handleInitializationRequest<T>(
 901			request: IncomingMessage,
 902			response: ServerResponse,
 903			body: T,
 904			sessionId: string | undefined,
 905			reservation: InitializationReservation | undefined,
 906		): Promise<boolean> {
 907			if (request.method !== "POST" || !isInitializeRequest(body)) return false;
 908			if (sessionId) {
 909				writeJson(
 910					response,
 911					400,
 912					"Initialization must not include Mcp-Session-Id.",
 913				);
 914				return true;
 915			}
 916			if (!reservation) {
 917				writeJson(
 918					response,
 919					503,
 920					"MCP initialization capacity is unavailable. Retry shortly.",
 921				);
 922				return true;
 923			}
 924			await handleInitializedSession(request, response, body, reservation);
 925			return true;
 926		}
