 928		async function handleExistingSessionRequest<T>(
 929			request: IncomingMessage,
 930			response: ServerResponse,
 931			body: T,
 932			sessionId: string | undefined,
 933			existingSession: HttpSession | undefined,
 934			trackedExistingResponse: boolean,
 935		): Promise<void> {
 936			if (!sessionId) {
 937				writeJson(response, 400, "Mcp-Session-Id header is required.");
 938				return;
 939			}
 940			const session = existingSession ?? sessions.get(sessionId);
 941			if (!session) {
 942				writeJson(response, 404, "Unknown Mcp-Session-Id.");
 943				return;
 944			}
 945			armIdleEviction(session);
 946			if (request.method !== "DELETE" && !trackedExistingResponse) {
 947				trackSessionResponse(session, response);
 948			}
 949			await runWithMcpSessionContext(session.context, () =>
 950				session.transport.handleRequest(request, response, body),
 951			);
 952			if (request.method === "DELETE" && !session.closed) {
 953				try {
 954					await closeSession(session);
 955				} catch (error) {
 956					cleanupErrors.push(error);
 957				}
 958			}
 959		}
