1013					writeJson(
1014						response,
1015						503,
1016						"HTTP server is shutting down. Retry shortly.",
1017					);
1018					return;
1019				}
1020				if (
1021					await handleInitializationRequest(
1022						request,
1023						response,
1024						body,
1025						resolution.sessionId,
1026						reservation ?? undefined,
1027					)
1028				)
1029					return;
1030				await handleExistingSessionRequest(
1031					request,
1032					response,
1033					body,
1034					resolution.sessionId,
1035					resolution.existingSession,
1036					resolution.trackedExistingResponse,
1037				);
