1071					}
1072					const sessionsToClose = [
1073						...new Set([...sessions.values(), ...pendingSessions]),
1074					];
1075					const results = await Promise.allSettled([
1076						...sessionsToClose.map((session) => closeSession(session)),
1077						closeServer(server),
1078					]);
1079					const initializationResults = await Promise.allSettled([
1080						...initializationPromises,
1081					]);
1082					sessions.clear();
1083					pendingSessions.clear();
1084					const errors = [
1085						...cleanupErrors,
1086						...results.flatMap((result) =>
1087							result.status === "rejected" ? [result.reason] : [],
1088						),
1089						...initializationResults.flatMap((result) =>
1090							result.status === "rejected" ? [result.reason] : [],
1091						),
1092					];
1093					await Effect.runPromise(Scope.close(httpScope, Exit.void)).catch(
1094						(error) => errors.push(error),
1095					);
1096					if (errors.length > 0) {
1097						throw aggregateErrors(errors, "HTTP server cleanup failed.");
1098					}
1099				})();
1100				return closePromise;
1101			},
1102		};
1103	}

