  1	import { Duration, Effect } from "effect";
  2	
  3	export type ShutdownSignal = "SIGINT" | "SIGTERM";
  4	
  5	interface CloseTarget {
  6		close(): Promise<void>;
  7	}
  8	
  9	interface ProcessLike {
 10		exitCode?: number | string | null;
 11		exit(code?: number | string | null): never;
 12		on(signal: ShutdownSignal, listener: () => void): unknown;
 13		removeListener(signal: ShutdownSignal, listener: () => void): unknown;
 14	}
 15	
 16	interface FlushableStdout {
 17		write(chunk: string, callback: (error?: Error | null) => void): boolean;
 18	}
 19	
 20	interface GracefulShutdownOptions {
 21		target: CloseTarget;
 22		closeTarget?: () => Promise<void>;
 23		process?: ProcessLike;
 24		logError?: (message: string) => void;
 25		flush?: () => Promise<void>;
 26		forcedExitTimeoutMs?: number;
 27		onComplete?: (succeeded: boolean) => void | Promise<void>;
 28		cancel?: AbortController;
 29	}
 30	
 31	export interface GracefulShutdownController {
 32		cleanup(): void;
 33		close(): Promise<void>;
 34		getShutdownPromise(): Promise<void> | undefined;
 35	}
 36	
 37	const shutdownSignals: ShutdownSignal[] = ["SIGINT", "SIGTERM"];
 38	
 39	// Long enough for normal stdio flushing, but bounded so unrelated handles or a
 40	// stalled close cannot keep a signal-terminated process alive indefinitely.
 41	export const FORCED_EXIT_TIMEOUT_MS = 5_000;
 42	
 43	export function flushStdout(
 44		stdout: FlushableStdout = process.stdout,
 45	): Promise<void> {
 46		return new Promise((resolve, reject) => {
 47			try {
 48				stdout.write("", (error) => {
 49					if (error) {
 50						reject(error);
 51						return;
 52					}
 53	
 54					resolve();
 55				});
 56			} catch (error) {
 57				reject(error);
 58			}
 59		});
 60	}
 61	
 62	export function installGracefulShutdown({
 63		target,
 64		process: processLike = process,
 65		logError = console.error,
 66		flush = flushStdout,
 67		closeTarget,
 68		forcedExitTimeoutMs = FORCED_EXIT_TIMEOUT_MS,
 69		cancel,
 70		onComplete,
 71	}: GracefulShutdownOptions): GracefulShutdownController {
 72		let shutdownSettled = false;
 73		let shutdownPromise: Promise<void> | undefined;
 74		let completionReported = false;
 75		let listenersCleaned = false;
 76		const installedListeners: Array<{
 77			signal: ShutdownSignal;
 78			listener: () => void;
 79		}> = [];
 80	
 81		const reportCompletion = (succeeded: boolean): Promise<void> | undefined => {
 82			if (completionReported) return undefined;
 83			completionReported = true;
 84			try {
 85				const completion = onComplete?.(succeeded);
 86				return completion
 87					? Promise.resolve(completion).catch(() => {
 88							logError("Graceful shutdown completion observer failed");
 89						})
 90					: undefined;
 91			} catch {
 92				logError("Graceful shutdown completion observer failed");
 93				return undefined;
 94			}
 95		};
 96	
 97		const cleanup = () => {
 98			if (listenersCleaned || (shutdownPromise && !shutdownSettled)) {
 99				return;
100			}
101	
102			listenersCleaned = true;
103			for (const { signal, listener } of installedListeners.toReversed()) {
104				try {
105					processLike.removeListener(signal, listener);
106				} catch {
107					// Cleanup must not replace the shutdown or registration error.
108				}
109			}
110		};
111	
112		const runShutdown = (
113			signal: ShutdownSignal | "close",
114			rejectOnFailure: boolean,
115		): Promise<void> => {
116			if (signal !== "close") {
117				if (processLike.exitCode == null) {
118					processLike.exitCode = 0;
119				}
120				cancel?.abort(
121					new DOMException(`Shutdown requested by ${signal}`, "AbortError"),
122				);
123			} else {
124				cancel?.abort(
125					new DOMException("Shutdown requested by close", "AbortError"),
126				);
127			}
128	
129			if (signal !== "close") {
130				logError(`Shutting down gracefully after ${signal}`);
131			}
132	
133			const shutdown = Effect.tryPromise({
134				try: async () => {
135					let shutdownError: unknown;
136					try {
137						await (closeTarget ? closeTarget() : target.close());
138					} catch (error) {
139						shutdownError = error;
140					}
141					try {
142						await flush();
143					} catch (error) {
144						shutdownError ??= error;
145					}
146					return { succeeded: shutdownError === undefined, shutdownError };
147				},
148				catch: (error) => ({ succeeded: false, shutdownError: error }),
149			});
150			const timed = Effect.race(
151				shutdown,
152				Effect.sleep(Duration.millis(forcedExitTimeoutMs)).pipe(
153					Effect.as({ succeeded: false, timedOut: true as const }),
154				),
155			);
156	
157			return Effect.runPromise(timed).then(async (result) => {
158				if ("timedOut" in result) {
159					await reportCompletion(false);
160					if (signal !== "close") {
161						processLike.exit(1);
162						return;
163					}
164					shutdownSettled = true;
165					cleanup();
166					if (rejectOnFailure) {
167						throw new Error("Graceful shutdown timed out.");
168					}
169					return;
170				}
171	
172				if (!result.succeeded) {
173					const message =
174						result.shutdownError instanceof Error
175							? result.shutdownError.message
176							: "Unknown shutdown error";
177					logError(`Graceful shutdown failed: ${message}`);
178					if (signal !== "close") {
179						processLike.exitCode = 1;
180					}
181				}
182				try {
183					await reportCompletion(result.succeeded);
184				} finally {
185					shutdownSettled = true;
186					cleanup();
187				}
188				if (!result.succeeded && rejectOnFailure) {
189					throw result.shutdownError instanceof Error
190						? result.shutdownError
191						: new Error("Graceful shutdown failed.");
192				}
193			});
194		};
195	
196		const handleSignal = (signal: ShutdownSignal) => {
197			if (shutdownPromise) {
198				return;
199			}
200	
201			shutdownPromise = runShutdown(signal, false).catch(() => undefined);
202		};
203	
204		const signalListeners = new Map<ShutdownSignal, () => void>(
205			shutdownSignals.map((signal) => [signal, () => handleSignal(signal)]),
206		);
207	
208		try {
209			for (const signal of shutdownSignals) {
210				const listener = signalListeners.get(signal);
211				if (listener) {
212					processLike.on(signal, listener);
213					installedListeners.push({ signal, listener });
214				}
215			}
216		} catch (error) {
217			cleanup();
218			throw error;
219		}
220	
221		return {
222			cleanup,
223			close: () => {
224				if (shutdownPromise) return shutdownPromise;
225				shutdownPromise = runShutdown("close", true);
226				return shutdownPromise;
227			},
228			getShutdownPromise: () => shutdownPromise,
229		};
230	}
