 40	const LIFECYCLE_FAILURE_TAXONOMY = {
 41		config: {
 42			errorType: "MCP_SERVER_CONFIG_ERROR",
 43			errorCategory: "McpServerConfigFailure",
 44		},
 45		api_key_validation: {
 46			errorType: "MCP_API_KEY_VALIDATION_ERROR",
 47			errorCategory: "McpApiKeyValidationFailure",
