157	function createOutcomeState(transport: NodeLifecycleTransport) {
158		let connectAttempted = false;
159		let connectSucceeded = false;
160		let listening = false;
161		return {
162			markConnectAttempted: () => {
163				connectAttempted = true;
164			},
165			markConnectSucceeded: () => {
166				connectSucceeded = true;
167			},
168			markListening: () => {
169				listening = true;
170			},
171			getOutcome: (): NodeLifecycleOutcome =>
172				transport === "stdio"
173					? { transport, connectAttempted, connectSucceeded }
174					: { transport, listening },
175		};
176	}
