178	function classifyFailure(
179		outcome: NodeLifecycleOutcome,
180	): LifecycleTerminationReason {
181		if (outcome.transport === "stdio") {
182			if (outcome.connectAttempted && !outcome.connectSucceeded) {
183				return "connect_failure";
184			}
185			return outcome.connectSucceeded ? "runtime_failure" : "startup_failure";
186		}
187		return outcome.listening ? "runtime_failure" : "startup_failure";
188	}
