194	/** Owns process-wide Node lifecycle concerns while leaving transport state local. */
195	export async function runNodeLifecycle({
196		transport,
197		start,
198		onFailure,
199	}: RunNodeLifecycleOptions): Promise<NodeLifecycleHandle> {
200		const processScope = await Effect.runPromise(Scope.make());
201		if (telemetryLayer) {
202			await Effect.runPromise(
203				Layer.buildWithScope(telemetryLayer, processScope).pipe(
204					Effect.catch(() => Effect.void),
205				),
206			);
207		}
208		const lifecycleController = new AbortController();
209		const state = createOutcomeState(transport);
210		let processScopeClosePromise: Promise<void> | undefined;
211		const closeProcessScope = (): Promise<void> => {
212			if (processScopeClosePromise) return processScopeClosePromise;
213			processScopeClosePromise = Effect.runPromise(
214				Scope.close(processScope, Exit.succeed(undefined)),
215			)
216				.catch(() => undefined)
217				.then(async () => {
218					// Keep compatibility with test doubles and alternate telemetry
219					// implementations that do not provide a Layer.
220					if (!telemetryLayer) await flushTelemetry().catch(() => undefined);
221				});
222			return processScopeClosePromise;
223		};
224	
225		let resolveReady: (handle: NodeLifecycleHandle) => void = () => undefined;
226		let rejectReady: (error?: Error | string | LifecycleFailure) => void = () =>
227			undefined;
228		const ready = new Promise<NodeLifecycleHandle>((resolve, reject) => {
229			resolveReady = resolve;
230			rejectReady = reject;
231		});
232		let resolveCompletion: () => void = () => undefined;
233		const completion = new Promise<void>((resolve) => {
234			resolveCompletion = resolve;
235		});
236		let completionReported = false;
237		const startupCleanups = new Set<() => Promise<void>>();
238		const adoptedTargets = new WeakMap<
239			NodeLifecycleTarget,
240			NodeLifecycleTarget
241		>();
242		const adoptTarget = (target: NodeLifecycleTarget): NodeLifecycleTarget => {
243			const existing = adoptedTargets.get(target);
244			if (existing) return existing;
245			let closePromise: Promise<void> | undefined;
246			const close = (): Promise<void> => {
247				if (closePromise) return closePromise;
248				closePromise = Promise.resolve()
249					.then(() => target.close())
250					.catch((error) => {
251						throw error;
252					});
253				return closePromise;
254			};
255			startupCleanups.add(close);
256			const adopted = { close };
257			adoptedTargets.set(target, adopted);
258			return adopted;
259		};
260		const context: NodeLifecycleContext = {
261			signal: lifecycleController.signal,
262			markConnectAttempted: () => state.markConnectAttempted(),
263			markConnectSucceeded: () => state.markConnectSucceeded(),
264			markListening: () => state.markListening(),
265			adoptTarget,
266		};
267	
268		serverStartups.add(1, { version: serviceVersion });
269		let span: Span | undefined;
270		const ownerProgram = Effect.gen(function* () {
271			yield* Effect.acquireRelease(
272				Effect.try({
273					try: installProcessExceptionTracking,
274					catch: (cause) =>
275						new LifecycleFailure({
276							cause: cause instanceof Error ? cause : String(cause),
277							phase: "run",
278						}),
279				}),
280				(cleanup) => Effect.sync(cleanup),
281			);
282			yield* Effect.acquireRelease(Effect.succeed(undefined), () =>
283				Effect.promise(async () => {
284					for (const cleanup of Array.from(startupCleanups).toReversed()) {
285						await cleanup().catch(() => undefined);
286					}
287				}),
288			);
289	
290			const result = yield* Effect.tryPromise({
291				try: () => start(context),
292				catch: (cause) =>
293					new LifecycleFailure({
294						cause: cause instanceof Error ? cause : String(cause),
295						phase: "run",
296					}),
297			});
298			const target = result.target;
299			const ownedTarget = adoptTarget(target);
300			const cancelUpdateCheck = yield* Effect.try({
301				try: () =>
302					scheduleUpdateCheck({
303						packageName: serviceName,
304						currentVersion: serviceVersion,
305					}),
306				catch: (cause) =>
307					new LifecycleFailure({
308						cause: cause instanceof Error ? cause : String(cause),
309						phase: "run",
310					}),
311			});
312			yield* Effect.acquireRelease(Effect.succeed(cancelUpdateCheck), (cancel) =>
313				Effect.sync(() => cancel?.()),
314			);
315	
316			const shutdown = yield* Effect.try({
317				try: () =>
318					installGracefulShutdown({
319						target,
320						closeTarget: () => ownedTarget.close(),
321						cancel: lifecycleController,
322						onComplete: async (succeeded) => {
323							if (completionReported) return;
324							completionReported = true;
325							try {
326								await result.onShutdown?.(succeeded);
327							} finally {
328								resolveCompletion();
329								await closeProcessScope();
330							}
331						},
332					}),
333				catch: (cause) =>
334					new LifecycleFailure({
335						cause: cause instanceof Error ? cause : String(cause),
336						phase: "run",
337					}),
338			});
339			if (shutdown) {
340				yield* Effect.acquireRelease(Effect.succeed(shutdown), (controller) =>
341					Effect.sync(() => controller.cleanup()),
342				);
343			}
344	
345			resolveReady({
346				close: shutdown ? () => shutdown.close() : () => target.close(),
347			});
348			span?.setStatus({ code: SpanStatusCode.OK });
349			if (!shutdown) resolveCompletion();
350			yield* Effect.promise(() => completion);
351		});
352	
353		const ownerFiber = await Effect.runPromise(
354			Effect.forkIn(
355				ownerProgram.pipe(
356					Effect.tapError((error) =>
357						Effect.sync(() => {
358							rejectReady(error);
359						}),
360					),
361				),
362				processScope,
363				{ startImmediately: true },
364			).pipe(Effect.provideService(Scope.Scope, processScope)),
365		);
366		const ownerCompletion = new Promise<void>((resolve) => {
367			ownerFiber.addObserver(() => {
368				void closeProcessScope().finally(resolve);
369			});
370		});
371	
372		await tracer.startActiveSpan(
373			"mcp.server.run",
374			{
375				attributes: {
376					"mcp.span.category": "startup",
377					"mcp.transport": transport,
378				},
379			},
380			async (startupSpan) => {
381				span = startupSpan;
382				try {
383					await ready;
384				} catch (error) {
385					const outcome = state.getOutcome();
386					const reason = classifyFailure(outcome);
387					const projectedError =
388						error instanceof LifecycleFailure
389							? asError(error.cause)
390							: asError(error instanceof Error ? error : String(error));
391					if (!(outcome.transport === "stdio" && reason === "connect_failure")) {
392						recordLifecycleFailure(startupSpan, projectedError, "run", reason);
393					}
394					onFailure?.(reason, outcome);
395					startupSpan.setStatus({ code: SpanStatusCode.ERROR });
396					await ownerCompletion;
397					throw projectedError;
398				} finally {
399					startupSpan.end();
400				}
401			},
402		);
403	
404		return await ready;
405	}
