220						const index = buffer.indexOf("\n");
221						if (index === -1) {
222							return null;
223						}
224	
225						const lineBuffer = buffer.subarray(0, index);
226						readBuffer._buffer = buffer.subarray(index + 1);
227						const line = lineBuffer.toString("utf8").replace(/\r$/, "");
228						try {
