388			"mcp.stdio.parse.line.byte_length": lineByteLength,
389			"mcp.stdio.parse.line.had_leading_bom": lineHadLeadingBom,
390			"mcp.stdio.parse.line.bom_stripped": lineHadLeadingBom,
391			"mcp.stdio.parse.chunk.last_byte_length": chunkSnapshot.lastChunkByteLength,
392			"mcp.stdio.parse.chunk.last_had_utf8_bom":
393				chunkSnapshot.lastChunkStartsWithUtf8Bom,
394		};
395		if (sessionId) attributes["mcp.session.id"] = sessionId;
396		return tracer.startActiveSpan(
397			"mcp.stdio.deserialize",
398			{
