408							span.setAttribute("mcp.method", method);
409						}
410						if (method === "initialize") {
411							const client = recordMcpSessionStart(message);
412							const sessionId = getCurrentMcpSessionId();
413							if (sessionId) {
414								span.setAttribute("mcp.session.id", sessionId);
415							}
416							span.setAttribute("mcp.client.name", client.name);
417							span.setAttribute("mcp.client.version", client.version);
418							span.setAttribute("mcp.protocol.version", client.protocolVersion);
419						}
420					}
421					return message;
422				} catch (error) {
423					const normalizedError = error instanceof Error ? error : String(error);
424					const diagnostic = createSafeErrorDiagnostic(normalizedError);
425					const failurePosition = parseFailurePosition(normalizedError);
426					const failureLocation = getFailureLocation(
427						failurePosition,
428						lineHadLeadingBom,
429					);
430	
431					span.setStatus({ code: SpanStatusCode.ERROR });
432					span.addEvent("mcp.stdio.parse.failure", {
433						"error.category": diagnostic.category,
434					});
435					span.setAttribute("mcp.stdio.parse.failure.location", failureLocation);
436					if (failurePosition !== null) {
437						span.setAttribute(
438							"mcp.stdio.parse.failure.position",
439							failurePosition,
440						);
441					}
442	
443					stdioParseErrors.add(1, { failure_location: failureLocation });
444	
445					reportStdinParseFailure(
446						error instanceof Error ? error : String(error),
447						line,
448						lineByteLength,
449						failureLocation,
450						failurePosition,
451					);
452	
453					throw error;
454				} finally {
455					span.end();
456				}
457			},
458		);
459	}
