461	export function createInstrumentedStdioTransport<
462		T extends StdioServerTransport,
463	>(transport: T): T {
464		const privateAdapter = createSdkPrivateStdioAdapter(transport);
465		let lastChunkSnapshot: StdioChunkSnapshot = {
466			lastChunkByteLength: 0,
467			lastChunkStartsWithUtf8Bom: false,
468		};
469	
470		privateAdapter.wrapOnData((chunk) => {
471			lastChunkSnapshot = {
472				lastChunkByteLength: chunk.byteLength,
473				lastChunkStartsWithUtf8Bom: hasUtf8BomPrefix(chunk),
474			};
475		});
476	
477		const didInstallReadMessageHook = privateAdapter.installReadMessageHook(
478			(line) => deserializeMessageWithObservability(line, lastChunkSnapshot),
479		);
480		if (!didInstallReadMessageHook) {
481			return transport;
482		}
483	
484		return transport;
485	}

