  1	import type { CacheObservationMetadata, CacheObserver } from "@hevy-mcp/core";
  2	import {
  3		diagnosticEndpointIdentity,
  4		metricEndpointIdentity,
  5		SAFE_OBSERVATION_CODES,
  6	} from "@hevy-mcp/hevy-client";
  7	import type {
  8		HevyClientOptions,
  9		HevyRequestObservation,
 10		HevyRequestStart,
 11	} from "@hevy-mcp/hevy-client";
 12	import { context, SpanStatusCode, trace, type Span } from "@opentelemetry/api";
 13	import { debugLog } from "./debug.js";
 14	import { apiCalls, apiDuration } from "./metrics.js";
 15	import { bucketCount } from "./result-telemetry.js";
 16	import {
 17		getCurrentMcpSessionId,
 18		getCurrentMcpTransport,
 19	} from "./mcp-session-observability.js";
 20	import { projectExecutionAttributes } from "./execution-telemetry.js";
 21	import { tracer } from "./telemetry.js";
 22	
 23	interface SafeErrorAttributes {
 24		error_category?: string;
 25		error_code?: string;
 26	}
 27	
 28	interface ApiSpanAttributes {
 29		[key: string]: string | number;
 30	}
 31	
 32	interface MetricAttributes {
 33		[key: string]: string | number | boolean;
 34	}
 35	
 36	interface DebugAttributes {
 37		[key: string]: string | number | boolean | null;
 38	}
 39	
 40	interface StringAttributes {
 41		[key: string]: string;
 42	}
 43	
 44	function safeErrorAttributes(
 45		observation: HevyRequestObservation,
 46	): SafeErrorAttributes {
 47		if (!observation.error) return {};
 48		const code = observation.error.code;
 49		const attributes: SafeErrorAttributes = {
 50			error_category: observation.error.category ?? "HevyHttpError",
 51		};
 52		if (code && SAFE_OBSERVATION_CODES.has(code)) attributes.error_code = code;
 53		return attributes;
 54	}
 55	
 56	function getDiagnosticResponseError(
 57		observation: HevyRequestObservation,
 58	): string | undefined {
 59		return process.env.HEVY_MCP_TELEMETRY_DIAGNOSTICS === "0"
 60			? undefined
 61			: observation.error?.response_error;
 62	}
 63	
 64	function startApiSpan(start: HevyRequestStart) {
 65		const sessionId = getCurrentMcpSessionId();
 66		const diagnosticEndpoint = diagnosticEndpointIdentity(start.endpoint);
 67		const attributes: ApiSpanAttributes = {
 68			"mcp.span.category": "api",
 69			"http.request.method": start.method,
 70			"hevy.api.retry_count_bucket": bucketCount(start.retryCount),
 71			"mcp.transport": getCurrentMcpTransport(),
 72		};
 73		if (diagnosticEndpoint) attributes["hevy.api.endpoint"] = diagnosticEndpoint;
 74		if (sessionId) attributes["mcp.session.id"] = sessionId;
 75		return tracer.startSpan(`hevy.api.${start.method}`, { attributes });
 76	}
 77	function finishApiSpan(span: Span, observation: HevyRequestObservation): void {
 78		const errorAttributes = safeErrorAttributes(observation);
 79		if (observation.status > 0) {
 80			span.setAttribute("http.response.status_code", observation.status);
 81		}
 82		for (const [key, value] of Object.entries(
 83			projectExecutionAttributes(observation),
 84		)) {
 85			span.setAttribute(key, value);
 86		}
 87		if (observation.expectedReason) {
 88			span.setAttribute("hevy.api.expected_reason", observation.expectedReason);
 89		}
 90		for (const [key, value] of Object.entries(errorAttributes)) {
 91			span.setAttribute(key, value);
 92		}
 93		span.setStatus({
 94			code:
 95				observation.outcome === "success" || observation.outcome === "expected"
 96					? SpanStatusCode.OK
 97					: SpanStatusCode.ERROR,
 98		});
 99		if (observation.outcome !== "success" && observation.outcome !== "expected") {
100			const responseError = getDiagnosticResponseError(observation);
101			const failureAttributes: StringAttributes = {
102				"error.category": errorAttributes.error_category ?? "HevyHttpError",
103			};
104			if (errorAttributes.error_code)
105				failureAttributes["error.code"] = errorAttributes.error_code;
106			if (responseError)
107				failureAttributes["hevy.api.response_error"] = responseError;
108			span.addEvent("hevy.api.failure", failureAttributes);
109		}
110		span.end();
111	}
112	
113	/** Node-only adapter; the Worker graph never imports telemetry or metrics. */
114	export function createNodeHevyClientOptions(): HevyClientOptions {
115		const rawTimeout = process.env.HEVY_MCP_API_TIMEOUT;
116		const parsedTimeout = rawTimeout ? Number(rawTimeout) : Number.NaN;
117		const timeoutMs =
118			Number.isFinite(parsedTimeout) && parsedTimeout > 0
119				? Math.floor(parsedTimeout)
120				: undefined;
121		const options: HevyClientOptions = {
122			onRequestStart(start) {
123				const span = startApiSpan(start);
124				return {
125					run<T>(operation: () => Promise<T>) {
126						return context.with(trace.setSpan(context.active(), span), operation);
127					},
128					finish(observation) {
129						finishApiSpan(span, observation);
130					},
131				};
132			},
133			onRequestComplete(observation) {
134				const retryCountBucket = bucketCount(observation.retryCount);
135				const errorAttributes = safeErrorAttributes(observation);
136				const responseError = getDiagnosticResponseError(observation);
137				const metricEndpoint = metricEndpointIdentity(observation.endpoint);
138				const diagnosticEndpoint = diagnosticEndpointIdentity(
139					observation.endpoint,
140				);
141				const metricExecutionAttributes = projectExecutionAttributes(
142					observation,
143					"metric",
144				);
145				const metricAttributes: MetricAttributes = {
146					...metricExecutionAttributes,
147					transport: getCurrentMcpTransport(),
148					...errorAttributes,
149				};
150				if (observation.expectedReason)
151					metricAttributes.expected_reason = observation.expectedReason;
152				apiCalls.add(1, {
153					method: observation.method,
154					endpoint: metricEndpoint,
155					status_code: observation.status,
156					retry_count_bucket: retryCountBucket,
157					...metricAttributes,
158				});
159				apiDuration.record(observation.durationMs, {
160					method: observation.method,
161					endpoint: metricEndpoint,
162					retry_count_bucket: retryCountBucket,
163					...metricAttributes,
164				});
165				const debugAttributes: DebugAttributes = {
166					method: observation.method,
167					durationMs: observation.durationMs,
168					status: observation.status || null,
169					retryCountBucket,
170					outcome: observation.outcome,
171					...errorAttributes,
172				};
173				if (diagnosticEndpoint) debugAttributes.endpoint = diagnosticEndpoint;
174				if (responseError) debugAttributes.response_error = responseError;
175				debugLog("api_response", debugAttributes);
176			},
177			onRetryWait(observation) {
178				const sessionId = getCurrentMcpSessionId();
179				const attributes: ApiSpanAttributes = {
180					"mcp.span.category": "api",
181					"http.request.method": observation.method,
182					"hevy.api.retry_count_bucket": bucketCount(observation.retryCount),
