import { request, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { McpServer } from "@modelcontextprotocol/server";
import { afterEach, describe, expect, it, vi } from "vitest";
import { startStreamableHttpServer } from "./streamable-http.js";

const handles: Array<{ close(): Promise<void> }> = [];
afterEach(async () => {
	await Promise.all(handles.splice(0).map((handle) => handle.close()));
	vi.restoreAllMocks();
});

interface HttpResult {
	statusCode?: number;
	headers: Record<string, string | string[] | undefined>;
	body: string;
}

function call(
	port: number,
	body: unknown,
	headers: Record<string, string>,
): Promise<HttpResult> {
	return new Promise((resolve, reject) => {
		const payload = JSON.stringify(body);
		const client = request(
			{ host: "127.0.0.1", port, path: "/mcp", method: "POST", headers },
			(response) => {
				const chunks: Buffer[] = [];
				response.on("data", (chunk: Buffer) => chunks.push(chunk));
				response.once("end", () =>
					resolve({
						statusCode: response.statusCode,
						headers: response.headers,
						body: Buffer.concat(chunks).toString("utf8"),
					}),
				);
			},
		);
		client.once("error", reject);
		client.end(payload);
	});
}

function serverPort(server: Server): number {
	const address = server.address() as AddressInfo;
	return address.port;
}

const initializeBody = {
	jsonrpc: "2.0",
	id: 1,
	method: "initialize",
	params: {
		protocolVersion: "2025-06-18",
		capabilities: {},
		clientInfo: { name: "bughunt", version: "1.0.0" },
	},
};

describe("bughunt: rejected initialize requests", () => {
	it("closes the per-session MCP server when the SDK rejects initialize before assigning a session id", async () => {
		vi.spyOn(console, "error").mockImplementation(() => undefined);
		let openServers = 0;
		const factory = () => {
			const server = new McpServer({ name: "bughunt", version: "1.0.0" });
			openServers += 1;
			const close = server.close.bind(server);
			let closed = false;
			server.close = async () => {
				if (!closed) {
					closed = true;
					openServers -= 1;
				}
				await close();
			};
			return Promise.resolve(server);
		};
		const handle = await startStreamableHttpServer(
			{ transport: "http", host: "127.0.0.1", port: 0 },
			"fake-key",
			factory,
			{ maxSessions: 2 },
		);
		handles.push(handle);
		const port = serverPort(handle.server);

		// A client that omits text/event-stream from Accept gets a 406 from the
		// SDK before onsessioninitialized fires. Repeat past maxSessions.
		const results: HttpResult[] = [];
		for (let attempt = 0; attempt < 5; attempt += 1) {
			results.push(
				await call(port, initializeBody, {
					Accept: "application/json",
					"Content-Type": "application/json",
				}),
			);
		}
		expect(results.map((result) => result.statusCode)).toEqual([
			406, 406, 406, 406, 406,
		]);
		expect(results.every((r) => r.headers["mcp-session-id"] === undefined)).toBe(
			true,
		);

		await new Promise((resolve) => setTimeout(resolve, 50));
		// No session was established, so no per-session server may stay alive
		// (and certainly not more than maxSessions of them).
		expect(openServers).toBe(0);
	});
});

