  1	/**
  2	 * Centralized telemetry initialization.
  3	 *
  4	 * It sets up independent telemetry paths: Sentry error events and an OTel
  5	 * Collector (traces + metrics to Honeycomb).
  6	 *
  7	 * Sentry SDK: error monitoring, release tracking
  8	 * OTel Collector → Honeycomb: performance traces, metrics
  9	 */
 10	
 11	import { randomBytes, randomUUID as nodeRandomUUID } from "node:crypto";
 12	import { z } from "zod";
 13	import { Effect, Layer } from "effect";
 14	import type { Tracer as EffectTracer } from "effect";
 15	import * as OtelResource from "@effect/opentelemetry/Resource";
 16	import * as OtelTracer from "@effect/opentelemetry/OtelTracer";
 17	import * as Sentry from "@sentry/node";
 18	import { context, metrics, trace } from "@opentelemetry/api";
 19	
 20	import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
 21	import {
 22		AggregationTemporalityPreference,
 23		OTLPMetricExporter,
 24	} from "@opentelemetry/exporter-metrics-otlp-http";
 25	import { resourceFromAttributes } from "@opentelemetry/resources";
 26	import {
 27		AlwaysOnSampler,
 28		BatchSpanProcessor,
 29		type SpanProcessor,
 30	} from "@opentelemetry/sdk-trace-base";
 31	import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
 32	import {
 33		MeterProvider,
 34		PeriodicExportingMetricReader,
 35	} from "@opentelemetry/sdk-metrics";
 36	import { captureFailure, sanitizeSentryEvent } from "./failure-reporter.js";
 37	import { sentryEnvironment, telemetryEnabled } from "./telemetry-config.js";
 38	export type ProcessExceptionSource = {
 39		on(
 40			event: "uncaughtExceptionMonitor" | "unhandledRejection",
 41			listener: (error: Error | string) => void,
 42		): void;
 43		removeListener(
 44			event: "uncaughtExceptionMonitor" | "unhandledRejection",
 45			listener: (error: Error | string) => void,
 46		): void;
 47	};
 48	
 49	const PROCESS_FAILURE_TAXONOMY = {
 50		uncaughtException: "uncaught_exception",
 51		unhandledRejection: "unhandled_rejection",
 52	} as const;
 53	
 54	export function installProcessExceptionTracking(
 55		processLike: ProcessExceptionSource = process,
 56	): () => void {
 57		if (!telemetryEnabled) return () => {};
 58		const recordProcessException = (
 59			source: keyof typeof PROCESS_FAILURE_TAXONOMY,
 60			error: Error | string,
 61		) => {
 62			try {
 63				tracer.startActiveSpan(
 64					`mcp.process.${source}`,
 65					{ attributes: { "mcp.span.category": "process" } },
 66					(span) => {
 67						try {
 68							captureFailure(error, {
 69								kind: "process",
 70								attributes: {
 71									"exception.source": source,
 72									"mcp.failure.phase": PROCESS_FAILURE_TAXONOMY[source],
 73									"error.type": "MCP_PROCESS_EXCEPTION",
 74									"error.category": "McpProcessFailure",
 75								},
 76								span,
 77							});
 78						} finally {
 79							span.end();
 80						}
 81					},
 82				);
 83			} catch {
 84				// Process telemetry must never affect Node's lifecycle.
 85			}
 86		};
 87		const uncaughtException = (error: Error | string) =>
 88			recordProcessException("uncaughtException", error);
 89		const unhandledRejection = (error: Error | string) =>
 90			recordProcessException("unhandledRejection", error);
 91		let cleaned = false;
 92		const installedListeners: Array<{
 93			event: "uncaughtExceptionMonitor" | "unhandledRejection";
 94			listener: (error: Error | string) => void;
 95		}> = [];
 96		const removeInstalledListeners = () => {
 97			if (cleaned) return;
 98			cleaned = true;
 99			for (const { event, listener } of installedListeners.toReversed()) {
100				try {
101					processLike.removeListener(event, listener);
102				} catch {
103					// Listener cleanup must not replace the original acquisition error.
104				}
105			}
106		};
107	
108		try {
109			const listeners = [
110				["uncaughtExceptionMonitor", uncaughtException],
111				["unhandledRejection", unhandledRejection],
112			] as const;
113			for (const [event, listener] of listeners) {
114				processLike.on(event, listener);
115				installedListeners.push({ event, listener });
116			}
117		} catch (error) {
118			removeInstalledListeners();
119			throw error;
120		}
121	
122		return () => {
123			removeInstalledListeners();
124		};
125	}
126	
127	function readBuildGlobal<T>(read: () => T): T | undefined {
128		try {
129			return read();
130		} catch {
131			return undefined;
132		}
133	}
134	
135	function parseBuildString<T>(value: T, fallback: string): string {
136		return z.string().parse(value ?? fallback);
137	}
138	declare const __HEVY_MCP_NAME__: string | undefined;
139	declare const __HEVY_MCP_VERSION__: string | undefined;
140	declare const __OTEL_COLLECTOR_TOKEN__: string | undefined;
141	
142	const name = parseBuildString(
143		readBuildGlobal(() => __HEVY_MCP_NAME__),
144		"hevy-mcp",
145	);
146	const version = parseBuildString(
147		readBuildGlobal(() => __HEVY_MCP_VERSION__),
148		"dev",
149	);
150	
151	// Collector token is injected at build time from the OTEL_COLLECTOR_TOKEN
152	// GitHub secret via tsdown.config.ts define. The collector forwards
153	// traces and metrics to Honeycomb, keeping the Honeycomb API key off the
154	// client. The collector endpoint is public (behind Cloudflare Tunnel).
155	const collectorToken =
156		z.string().safeParse(readBuildGlobal(() => __OTEL_COLLECTOR_TOKEN__)).data ??
157		process.env.OTEL_COLLECTOR_TOKEN ??
158		"";
159	
160	const COLLECTOR_ENDPOINT = "https://otel.chrisdoc.dev/v1";
161	const DEFAULT_SENTRY_DSN =
162		"https://ce696d8333b507acbf5203eb877bce0f@o4508975499575296.ingest.de.sentry.io/4509049671647312";
163	const sentryRelease = process.env.SENTRY_RELEASE ?? `${name}@${version}`;
164	
165	/** Hex-encode bytes without relying on Buffer typings that vary across @types/node releases. */
166	function toHex(bytes: Uint8Array): string {
167		let hex = "";
168		for (const byte of bytes) hex += byte.toString(16).padStart(2, "0");
169		return hex;
170	}
171	
172	export function createServiceInstanceId(
173		generate: () => string = nodeRandomUUID,
174	): string {
175		try {
176			const generated = generate();
177			if (generated.length > 0 && generated.length <= 128) return generated;
178		} catch {
179			// Fall back to a process-local opaque identifier.
180		}
181		return toHex(randomBytes(16));
182	}
183	
184	const serviceInstanceId = createServiceInstanceId();
185	
186	const resource = resourceFromAttributes({
187		"service.name": name,
188		"service.version": version,
189		"service.instance.id": serviceInstanceId,
190		"process.runtime.name": process.release.name,
191		"process.runtime.version": process.version,
192	});
193	
194	let tracerProvider: NodeTracerProvider | undefined;
195	let meterProvider: MeterProvider | undefined;
196	let telemetryInitialized = false;
197	
198	export type TelemetryAvailability =
199		| "telemetry_disabled"
200		| "telemetry_unavailable"
201		| "available";
202	
203	function initializeTelemetry(): void {
204		if (telemetryInitialized || !telemetryEnabled) return;
205		try {
206			const rawDsn = process.env.SENTRY_DSN ?? DEFAULT_SENTRY_DSN;
207			const isValidDsn =
208				z.string().safeParse(rawDsn).success &&
209				rawDsn.length > 0 &&
210				!rawDsn.startsWith("*");
211	
212			// --- Sentry error monitoring ---
213			Sentry.init({
214				dsn: isValidDsn ? rawDsn : undefined,
215				release: sentryRelease,
216				environment: sentryEnvironment,
217				tracesSampleRate: 0.0,
218				sendClientReports: false,
219				dataCollection: { userInfo: false },
220				beforeSend: sanitizeSentryEvent,
221				integrations: (integrations) =>
222					integrations.filter(
223						(integration) =>
224							integration.name !== "OnUncaughtException" &&
225							integration.name !== "OnUnhandledRejection",
226					),
227				enableOpenTelemetrySetup: false,
228				ignoreErrors: ["EPIPE", "broken pipe"],
229			});
230	
231			const spanProcessors: SpanProcessor[] = [];
232	
233			// OTel Collector → Honeycomb traces — only if token is available
234			if (collectorToken) {
235				spanProcessors.push(
236					new BatchSpanProcessor(
237						new OTLPTraceExporter({
238							url: `${COLLECTOR_ENDPOINT}/traces`,
239							headers: {
240								Authorization: `Bearer ${collectorToken}`,
241							},
242						}),
243					),
244				);
245			}
246	
247			tracerProvider = new NodeTracerProvider({
248				resource,
249				sampler: new AlwaysOnSampler(),
250				spanProcessors,
251			});
252	
253			tracerProvider.register();
254	
255			// --- OpenTelemetry meter provider (→ Collector → Honeycomb metrics) ---
256			if (collectorToken) {
