485		const record = normalizeFailure(error, context);
486		const traceContext = getTraceContext(span);
487		if (traceContext.traceId) {
488			record.attributes["otel.trace_id"] = traceContext.traceId;
489		}
490		if (traceContext.spanId) {
491			record.attributes["otel.span_id"] = traceContext.spanId;
492		}
493	
494		const diagnosticId = getDiagnosticId(error);
495		if (diagnosticId) record.attributes["mcp.failure.id"] = diagnosticId;
496	
497		const { expected } = record;
498		const duplicate = expected ? false : hasReportedError(error);
