518			}
519		}
520	
521		if (span) {
522			try {
523				if (!duplicate && !expected) {
524					span.recordException(record.exception);
525					if (record.responseError) {
526						span.addEvent("mcp.failure.detail", {
527							"hevy.api.response_error": record.responseError,
528						});
529					}
530				}
