532				if (!expected) {
533					span.setStatus({ code: SpanStatusCode.ERROR });
534				}
535				if (eventId) span.setAttribute("sentry.event_id", eventId);
536			} catch {
537				// OTel failures must never affect MCP behavior.
538			}
539		}
540	
541		const receipt: Mutable<FailureReceipt> = {};
542		if (diagnosticId) receipt.diagnosticId = diagnosticId;
543		if (eventId) receipt.eventId = eventId;
544		if (traceContext.traceId) receipt.traceId = traceContext.traceId;
545		if (traceContext.spanId) receipt.spanId = traceContext.spanId;
546		return receipt;
547	}

