321			normalized.exception.stack = stack;
322		}
323		if (responseError) normalized.responseError = responseError;
324		return normalized as NormalizedFailure;
325	}
326	
327	function sanitizeContext<T>(value: T): TelemetryAttributes {
328		if (!isObject(value)) return {};
329		const output: TelemetryAttributes = {};
330		for (const [key, rawValue] of Object.entries(value).slice(0, 32)) {
331			if (
332				key !== "kind" &&
333				!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))
334			) {
335				continue;
336			}
337			if (!isString(rawValue) && !isNumber(rawValue) && !isBoolean(rawValue)) {
338				continue;
339			}
340			if (isNumber(rawValue) && !Number.isFinite(rawValue)) {
341				continue;
342			}
343			output[truncate(key, 128)] = sanitizeAttributeValue(key, rawValue);
344		}
345		return output;
346	}
347	
348	function sanitizeSentryTags(tags: ErrorEvent["tags"]): ErrorEvent["tags"] {
349		if (!tags) return undefined;
350		const output: NonNullable<ErrorEvent["tags"]> = {};
351		for (const [key, value] of Object.entries(tags)) {
352			if (!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))) continue;
353			if (!isString(value) && !isNumber(value) && !isBoolean(value)) {
354				continue;
355			}
356			output[truncate(key, 128)] = isString(value)
357				? sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH)
358				: value;
359		}
360		return output;
361	}
362	
363	function normalizeStackFilename(value: string): string {
364		const sanitized = sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
365		const distMarker = sanitized.lastIndexOf("/dist/");
366		return distMarker >= 0 ? `~${sanitized.slice(distMarker)}` : sanitized;
367	}
368	
369	function sanitizeSentryExceptionValues(
370		event: ErrorEvent,
371	): ErrorEvent["exception"] {
372		const values = event.exception?.values;
373		if (!values) return undefined;
374		return {
375			values: values.map((value) => {
376				const safeValue: Mutable<SentryExceptionValue> = {};
377				if (value.type)
378					safeValue.type = sanitizeDiagnosticText(
379						value.type,
380						MAX_ATTRIBUTE_LENGTH,
381					);
382				if (value.value)
383					safeValue.value = sanitizeDiagnosticText(
384						value.value,
385						MAX_MESSAGE_LENGTH,
386					);
387				if (value.stacktrace) {
388					safeValue.stacktrace = {
389						frames: value.stacktrace.frames?.map((frame) => {
390							const safeFrame: Mutable<SentryStackFrame> = {};
391							if (frame.filename)
392								safeFrame.filename = normalizeStackFilename(frame.filename);
393							if (frame.function)
394								safeFrame.function = sanitizeDiagnosticText(
395									frame.function,
396									MAX_ATTRIBUTE_LENGTH,
397								);
398							if (isNumber(frame.lineno)) safeFrame.lineno = frame.lineno;
399							if (isNumber(frame.colno)) safeFrame.colno = frame.colno;
400							if (isBoolean(frame.in_app)) safeFrame.in_app = frame.in_app;
401							return safeFrame;
402						}),
403					};
404				}
405				return safeValue;
406			}),
407		};
408	}
409	
410	/** Final Sentry-side safety net for SDK-generated event fields and integrations. */
411	export function sanitizeSentryEvent(
412		event: ErrorEvent,
413		_hint?: EventHint,
414	): ErrorEvent {
415		const sanitized: ErrorEvent = {
416			...event,
417			request: undefined,
418			user: undefined,
419			server_name: undefined,
420			breadcrumbs: undefined,
421			extra: undefined,
422			logentry: undefined,
423			threads: undefined,
424			sdkProcessingMetadata: undefined,
425			contexts: event.contexts?.mcp
426				? { mcp: sanitizeContext(event.contexts.mcp) }
427				: undefined,
428			tags: sanitizeSentryTags(event.tags),
429			exception: sanitizeSentryExceptionValues(event),
430			spans: undefined,
431		};
432		if (event.message)
433			sanitized.message = sanitizeDiagnosticText(
434				event.message,
435				MAX_MESSAGE_LENGTH,
436			);
437		return sanitized;
438	}
439	
440	function createSentryError(record: NormalizedFailure): Error {
441		const error = new Error(record.message ?? record.exceptionType);
442		error.name = record.exceptionType;
443		if (record.stack) error.stack = record.stack;
444		return error;
445	}
446	
447	function setSpanAttributes(span: Span, attributes: TelemetryAttributes): void {
448		try {
449			span.setAttributes(attributes);
450		} catch {
451			// Telemetry must never alter application behavior.
452		}
453	}
454	
455	const reportedErrors = new WeakSet<object>();
456	const diagnosticIds = new WeakMap<object, string>();
457	
458	function getDiagnosticId<T>(error: T): string | undefined {
459		if (isObject(error)) {
460			const existing = diagnosticIds.get(error);
461			if (existing) return existing;
462		}
463		try {
464			const generated = randomUUID();
465			if (isObject(error)) diagnosticIds.set(error, generated);
466			return generated;
467		} catch {
468			return undefined;
469		}
470	}
471	
472	function hasReportedError<T>(error: T): boolean {
473		if (!isObject(error)) return false;
474		if (reportedErrors.has(error)) return true;
475		reportedErrors.add(error);
476		return false;
477	}
478	
479	export function captureFailure<T>(
480		error: T,
481		context: FailureContext,
482	): FailureReceipt | undefined {
483		if (!telemetryEnabled) return undefined;
484		const span = context.span ?? trace.getActiveSpan() ?? undefined;
485		const record = normalizeFailure(error, context);
486		const traceContext = getTraceContext(span);
487		if (traceContext.traceId) {
488			record.attributes["otel.trace_id"] = traceContext.traceId;
489		}
490		if (traceContext.spanId) {
491			record.attributes["otel.span_id"] = traceContext.spanId;
492		}
493	
494		const diagnosticId = getDiagnosticId(error);
495		if (diagnosticId) record.attributes["mcp.failure.id"] = diagnosticId;
496	
497		const { expected } = record;
498		const duplicate = expected ? false : hasReportedError(error);
499		let eventId: string | undefined;
500		if (!duplicate && !expected) {
501			try {
502				eventId = Sentry.withScope((scope) => {
503					for (const [key, value] of Object.entries(record.attributes)) {
504						scope.setTag(key, String(value));
505					}
506					scope.setFingerprint([...record.fingerprint]);
507					const sentryContext: SentryContext = {
508						kind: context.kind,
509						...record.attributes,
510					};
511					if (record.responseError)
512						sentryContext["hevy.api.response_error"] = record.responseError;
513					scope.setContext("mcp", sentryContext);
514					return Sentry.captureException(createSentryError(record));
515				});
516			} catch {
517				// Sentry failures must never affect MCP behavior.
518			}
519		}
520	
521		if (span) {
522			try {
523				if (!duplicate && !expected) {
524					span.recordException(record.exception);
525					if (record.responseError) {
526						span.addEvent("mcp.failure.detail", {
527							"hevy.api.response_error": record.responseError,
528						});
529					}
530				}
531				setSpanAttributes(span, record.attributes);
532				if (!expected) {
533					span.setStatus({ code: SpanStatusCode.ERROR });
534				}
535				if (eventId) span.setAttribute("sentry.event_id", eventId);
536			} catch {
537				// OTel failures must never affect MCP behavior.
538			}
539		}
540	
541		const receipt: Mutable<FailureReceipt> = {};
542		if (diagnosticId) receipt.diagnosticId = diagnosticId;
543		if (eventId) receipt.eventId = eventId;
544		if (traceContext.traceId) receipt.traceId = traceContext.traceId;
545		if (traceContext.spanId) receipt.spanId = traceContext.spanId;
546		return receipt;
547	}

