  1	import { AsyncLocalStorage } from "node:async_hooks";
  2	import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
  3	import type {
  4		JSONRPCRequest,
  5		McpServer,
  6		PerRequestMessageExtra,
  7	} from "@modelcontextprotocol/server";
  8	import { createSafeErrorDiagnostic, ErrorType } from "@hevy-mcp/core";
  9	import type { NodeTransport } from "./arguments.js";
 10	import {
 11		getCurrentMcpSessionId,
 12		getCurrentMcpTransport,
 13	} from "./mcp-session-observability.js";
 14	import { projectExecutionAttributes } from "./execution-telemetry.js";
 15	import { captureFailure, tracer } from "./telemetry.js";
 16	import { z } from "zod";
 17	
 18	type SdkRequestHandler = (
 19		request: JSONRPCRequest,
 20		extra: PerRequestMessageExtra,
 21	) => Promise<unknown>;
 22	
 23	interface SdkProtocolInternals {
 24		_requestHandlers?: Map<string, SdkRequestHandler>;
 25	}
 26	
 27	interface SdkToolErrorHost {
 28		createToolError?: (message: string) => unknown;
 29		onerror?: (error: Error) => void;
 30	}
 31	
 32	const sdkToolErrorHostSchema = z.custom<SdkToolErrorHost>(
 33		(value) =>
 34			z.object({ createToolError: z.function() }).passthrough().safeParse(value)
 35				.success,
 36	);
 37	const sdkProtocolInternalsSchema = z.custom<SdkProtocolInternals>(
 38		(value) =>
 39			z
 40				.object({ _requestHandlers: z.instanceof(Map) })
 41				.passthrough()
 42				.safeParse(value).success,
 43	);
 44	
 45	interface ToolResultLike {
 46		isError?: unknown;
 47	}
 48	
 49	type FailureAttributes = Record<string, string | number | boolean>;
 50	type SdkFailureKind = "protocol" | "tool_call" | "validation";
 51	type SdkValidationKind = "input" | "output" | "tool_not_found" | "unknown";
 52	
 53	interface SdkFailureTaxonomy {
 54		readonly [key: string]: { errorType: ErrorType; errorCategory: string };
 55	}
 56	
 57	interface SdkValidationResult {
 58		kind: SdkValidationKind;
 59		expected: boolean;
 60		toolName?: string;
 61	}
 62	
 63	type SdkFailureOptions = {
 64		expected?: boolean;
 65		validationKind?: SdkValidationKind;
 66	};
 67	
 68	const sdkToolNameStorage = new AsyncLocalStorage<string>();
 69	const sdkRequestStateStorage = new AsyncLocalStorage<{
 70		expectedValidation?: boolean;
 71	}>();
 72	const SAFE_TOOL_NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/u;
 73	const SDK_FAILURE_TAXONOMY: SdkFailureTaxonomy = {
 74		protocol: {
 75			errorType: ErrorType.UNKNOWN_ERROR,
 76			errorCategory: "McpSdkProtocolFailure",
 77		},
 78		tool_call: {
 79			errorType: ErrorType.UNKNOWN_ERROR,
 80			errorCategory: "McpSdkToolCallFailure",
 81		},
 82		validation: {
 83			errorType: ErrorType.VALIDATION_ERROR,
 84			errorCategory: "McpSdkValidationFailure",
 85		},
 86	};
 87	
 88	function createFailureAttributes(
 89		error: Error | string,
 90		phase: "discovery" | "sdk",
 91		errorType: string,
 92		errorCategory: string,
 93	): FailureAttributes {
 94		const diagnostic = createSafeErrorDiagnostic(error);
 95		const attributes: FailureAttributes = {
 96			"mcp.failure.phase": phase,
 97			"error.type": errorType,
 98			"error.category": errorCategory,
 99			...projectExecutionAttributes(diagnostic),
100		};
101		if (diagnostic.code) attributes["error.code"] = diagnostic.code;
102		if (diagnostic.status !== undefined)
103			attributes["http.response.status_code"] = diagnostic.status;
104		if (diagnostic.method) attributes["http.request.method"] = diagnostic.method;
105		if (diagnostic.endpoint)
106			attributes["hevy.api.endpoint"] = diagnostic.endpoint;
107		return attributes;
108	}
109	
110	function enrichActiveSdkSpan(attributes: FailureAttributes): void {
111		try {
112			trace.getActiveSpan()?.setAttributes(attributes);
113		} catch {
114			// SDK span enrichment is best-effort and cannot affect protocol handling.
115		}
116	}
117	
118	function getSdkToolName(request: JSONRPCRequest): string {
119		const parsed = z
120			.object({ params: z.object({ name: z.string().optional() }).optional() })
121			.safeParse(request);
122		const candidate = parsed.success ? parsed.data.params?.name : undefined;
123		return candidate && SAFE_TOOL_NAME_PATTERN.test(candidate)
124			? candidate
125			: "unknown";
126	}
127	
128	function markSdkToolFailure(
129		span: Span,
130		error: Error | string,
131		toolName = sdkToolNameStorage.getStore() ?? "unknown",
132		kind: SdkFailureKind = "tool_call",
133		options: SdkFailureOptions = {},
134	): void {
135		const taxonomy = SDK_FAILURE_TAXONOMY[kind];
136		const attributes: FailureAttributes = {
137			"mcp.tool.name": toolName,
138			...createFailureAttributes(
139				error,
140				"sdk",
141				taxonomy.errorType,
142				taxonomy.errorCategory,
143			),
144		};
145		if (options.validationKind)
146			attributes["mcp.validation.kind"] = options.validationKind;
147		span.addEvent("mcp.tool.failure", attributes);
148		span.setAttribute("error.type", taxonomy.errorType);
149		captureFailure(error, {
150			kind: "sdk",
151			attributes,
152			span,
153			expected: options.expected,
154		});
155		if (options.expected !== true) {
156			span.setStatus({ code: SpanStatusCode.ERROR });
157		}
158	}
159	
160	function installProtocolErrorTracking(
161		server: { server?: { onerror?: (error: Error) => void } },
162		transport: NodeTransport,
163	): void {
164		const protocol = server.server;
165		if (!protocol) return;
166		const previous = protocol.onerror;
167		protocol.onerror = (error) => {
168			const taxonomy = SDK_FAILURE_TAXONOMY.protocol;
169			const attributes = createFailureAttributes(
170				error,
171				"sdk",
172				taxonomy.errorType,
173				taxonomy.errorCategory,
174			);
175			const activeSpan = trace.getActiveSpan();
176			const sessionId = getCurrentMcpSessionId();
177			if (activeSpan) {
178				activeSpan.addEvent("mcp.tool.failure", {
179					"mcp.tool.name": sdkToolNameStorage.getStore() ?? "unknown",
180					...attributes,
181				});
182				captureFailure(error, {
183					kind: "protocol",
184					attributes,
185					span: activeSpan,
186				});
187			} else {
188				tracer.startActiveSpan(
189					"mcp.sdk.failure",
190					{
191						attributes: (() => {
192							const spanAttributes: FailureAttributes = {
193								"mcp.span.category": "protocol",
194								"mcp.transport": transport,
195							};
196							if (sessionId) spanAttributes["mcp.session.id"] = sessionId;
197							return spanAttributes;
198						})(),
199					},
200					(span) => {
201						span.addEvent("mcp.tool.failure", {
202							"mcp.tool.name": "unknown",
203							...attributes,
204						});
205						captureFailure(error, { kind: "protocol", attributes, span });
206						span.end();
207					},
208				);
209			}
210			try {
211				previous?.(error);
212			} catch {
213				// Existing SDK/Sentry handlers must not affect protocol behavior.
214			}
215		};
216	}
217	
218	function classifySdkValidation(message: string): SdkValidationResult {
219		const inputValidation =
220			/^Input validation error: Invalid arguments for tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63})(?::|$)/u.exec(
221				message,
222			);
223		if (inputValidation) {
224			return {
225				kind: "input",
226				expected: true,
227				toolName: inputValidation[1],
228			};
229		}
230		if (message.startsWith("Input validation error:")) {
231			return { kind: "input", expected: true };
232		}
233		if (message.startsWith("Output validation error:")) {
234			return { kind: "output", expected: false };
235		}
236		const missingTool =
237			/^Tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63}) not found$/u.exec(message);
238		if (missingTool) {
239			return {
240				kind: "tool_not_found",
241				expected: true,
242				toolName: missingTool[1],
243			};
244		}
245		return { kind: "unknown", expected: false };
246	}
247	
248	function installValidationErrorTracking(server: McpServer): void {
249		const parsedHost = sdkToolErrorHostSchema.safeParse(server);
250		if (!parsedHost.success) return;
251		const toolErrorHost = parsedHost.data;
252		const previousCreateToolError = toolErrorHost.createToolError;
253		if (!previousCreateToolError) return;
254		const createToolError = previousCreateToolError.bind(server);
255		toolErrorHost.createToolError = (message) => {
256			const validation = classifySdkValidation(message);
257			const requestState = sdkRequestStateStorage.getStore();
258			if (requestState) requestState.expectedValidation = validation.expected;
259			const result = createToolError(message);
260			const activeSpan = trace.getActiveSpan();
261			if (activeSpan) {
262				markSdkToolFailure(
263					activeSpan,
264					new Error(
265						validation.kind === "output"
266							? "MCP tool output validation failed"
267							: "MCP tool validation failed",
268					),
269					sdkToolNameStorage.getStore() ?? validation.toolName ?? "unknown",
270					"validation",
271					{
272						expected: validation.expected,
273						validationKind: validation.kind,
274					},
275				);
276			}
277			return result;
278		};
279	}
280	
281	function installInitializeEnrichment(
282		handlers: Map<string, SdkRequestHandler>,
283		transport: NodeTransport,
284	): void {
285		const initializeHandler = handlers.get("initialize");
286		if (!initializeHandler) return;
287		handlers.set("initialize", (request, extra) => {
288			enrichActiveSdkSpan({
289				"mcp.span.category": "protocol",
290				"mcp.transport": transport,
291			});
292			return initializeHandler(request, extra);
293		});
294	}
295	
296	function installToolCallTracking(
297		handlers: Map<string, SdkRequestHandler>,
298		transport: NodeTransport,
299	): void {
300		const toolHandler = handlers.get("tools/call");
301		if (!toolHandler) return;
302		handlers.set("tools/call", (request, extra) => {
303			const sessionId = getCurrentMcpSessionId();
304			const toolName = getSdkToolName(request);
305			const attributes: FailureAttributes = {
306				"mcp.span.category": "protocol",
307				"mcp.transport": transport,
308				"mcp.operation.kind": "tool",
309				"mcp.tool.name": toolName,
310			};
311			if (sessionId) attributes["mcp.session.id"] = sessionId;
312			enrichActiveSdkSpan(attributes);
313			return sdkToolNameStorage.run(toolName, () =>
314				sdkRequestStateStorage.run({}, () =>
315					tracer.startActiveSpan(
316						"mcp.sdk.tools.call",
317						{ attributes },
318						async (span) => {
319							try {
320								const result = (await toolHandler(
321									request,
322									extra,
323								)) as ToolResultLike;
324								if (result?.isError === true) {
325									span.setAttribute("mcp.tool.outcome", "returned_error");
326									if (
327										sdkRequestStateStorage.getStore()?.expectedValidation !== true
328									) {
329										span.setStatus({ code: SpanStatusCode.ERROR });
330									}
331								} else {
332									span.setStatus({ code: SpanStatusCode.OK });
333								}
334								return result;
335							} catch (error) {
336								const validation =
337									error instanceof Error
338										? classifySdkValidation(error.message)
339										: { kind: "unknown" as const, expected: false };
340								if (validation.kind === "tool_not_found") {
341									markSdkToolFailure(
342										span,
343										error instanceof Error ? error : String(error),
344										toolName,
345										"validation",
346										{
347											expected: true,
348											validationKind: validation.kind,
349										},
350									);
351								} else {
352									markSdkToolFailure(
353										span,
354										error instanceof Error ? error : String(error),
355										toolName,
356									);
357								}
358								throw error;
359							} finally {
360								span.end();
361							}
362						},
363					),
364				),
365			);
366		});
367	}
368	
369	function installDiscoveryTracking(
370		handlers: Map<string, SdkRequestHandler>,
371	): void {
372		const discoveryHandler = handlers.get("server/discover");
373		if (!discoveryHandler) return;
374		handlers.set("server/discover", (request, extra) => {
375			const sessionId = getCurrentMcpSessionId();
376			return tracer.startActiveSpan(
377				"mcp.server.discover",
378				{
379					attributes: (() => {
380						const attributes: FailureAttributes = {
381							"mcp.span.category": "discovery",
382							"mcp.transport": getCurrentMcpTransport(),
383						};
384						if (sessionId) attributes["mcp.session.id"] = sessionId;
385						return attributes;
386					})(),
387				},
388				async (span) => {
389					try {
390						const result = await discoveryHandler(request, extra);
391						span.setStatus({ code: SpanStatusCode.OK });
392						return result;
393					} catch (error) {
394						const normalizedError =
395							error instanceof Error ? error : String(error);
396						const attributes = createFailureAttributes(
397							normalizedError,
398							"discovery",
399							ErrorType.UNKNOWN_ERROR,
400							"McpServerDiscoveryFailure",
401						);
402						span.addEvent("mcp.discovery.failure", attributes);
403						captureFailure(normalizedError, {
404							kind: "discovery",
405							attributes,
406							span,
407						});
408						throw error;
409					} finally {
410						span.end();
411					}
412				},
413			);
414		});
415	}
416	
417	export function installSdkErrorTracking(
418		server: McpServer,
419		transport: NodeTransport,
420	): void {
421		installProtocolErrorTracking(server, transport);
422		installValidationErrorTracking(server);
423		const parsedInternals = sdkProtocolInternalsSchema.safeParse(server.server);
424		if (!parsedInternals.success) return;
425		const handlers = parsedInternals.data._requestHandlers;
426		if (!(handlers instanceof Map)) return;
427		installInitializeEnrichment(handlers, transport);
428		installToolCallTracking(handlers, transport);
429		installDiscoveryTracking(handlers);
430	}

