 22	type RedactedValue =
 23		| number
 24		| bigint
 25		| string
 26		| {
 27				type: "array";
 28				length: number;
 29				items: Record<string, RedactedValue> | "[max-depth]";
 30				truncatedItems?: number;
 31		  }
 32		| {
 33				type: "object";
 34				fieldCount: number;
 35				fields: Record<string, RedactedValue> | "[max-depth]";
 36				truncatedFields?: number;
 37		  };
 38	
 39	type DebugData = {
 40		readonly [key: string]: string | number | boolean | null | RedactedValue;
 41	};
 42	
 43	export function isDebugEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
 44		return env.HEVY_MCP_DEBUG === "1";
 45	}
 46	
 47	function redactValue<T>(
 48		value: T,
 49		depth: number,
 50		seen: WeakSet<object>,
 51	): RedactedValue {
 52		if (value === null) {
 53			return "[null]";
 54		}
 55	
 56		if (!isObjectLike(value)) {
 57			return `[${scalarTag(value)}]`;
 58		}
 59	
 60		if (seen.has(value)) {
 61			return "[circular]";
 62		}
 63	
 64		if (Array.isArray(value)) {
 65			const lengthDescriptor = Object.getOwnPropertyDescriptor(value, "length");
 66			const length =
 67				lengthDescriptor &&
 68				"value" in lengthDescriptor &&
 69				numberSchema.safeParse(lengthDescriptor.value).success
 70					? lengthDescriptor.value
 71					: 0;
 72			if (depth >= MAX_REDACTION_DEPTH) {
 73				return { type: "array", length, items: "[max-depth]" };
 74			}
 75	
 76			seen.add(value);
 77			try {
 78				const itemCount = Math.min(length, MAX_OBJECT_KEYS);
 79				const items: Record<string, RedactedValue> = {};
 80				for (let index = 0; index < itemCount; index += 1) {
 81					const descriptor = Object.getOwnPropertyDescriptor(
 82						value,
 83						String(index),
 84					);
 85					items[`item-${index + 1}`] =
 86						descriptor && "value" in descriptor
 87							? redactValue(descriptor.value, depth + 1, seen)
 88							: "[empty-or-accessor]";
 89				}
 90	
 91				const result: Extract<RedactedValue, { type: "array" }> = {
 92					type: "array",
 93					length,
 94					items,
 95				};
 96				if (length > MAX_OBJECT_KEYS)
 97					result.truncatedItems = length - MAX_OBJECT_KEYS;
 98				return result;
 99			} finally {
100				seen.delete(value);
101			}
102		}
103	
104		const keys = Object.keys(value);
105		if (depth >= MAX_REDACTION_DEPTH) {
106			return {
107				type: "object",
108				fieldCount: keys.length,
109				fields: "[max-depth]",
110			};
111		}
112	
113		seen.add(value);
114		try {
115			const fields: Record<string, RedactedValue> = {};
116			for (const [index, rawKey] of keys.slice(0, MAX_OBJECT_KEYS).entries()) {
117				const descriptor = Object.getOwnPropertyDescriptor(value, rawKey);
118				fields[`field-${index + 1}`] =
119					descriptor && "value" in descriptor
120						? redactValue(descriptor.value, depth + 1, seen)
121						: "[accessor]";
122			}
123	
124			const result: Extract<RedactedValue, { type: "object" }> = {
125				type: "object",
126				fieldCount: keys.length,
127				fields,
128			};
129			if (keys.length > MAX_OBJECT_KEYS)
130				result.truncatedFields = keys.length - MAX_OBJECT_KEYS;
131			return result;
132		} finally {
133			seen.delete(value);
134		}
135	}
136	
137	/** Redact every input scalar while preserving bounded argument structure. */
138	export function redactToolArgs<T>(args: T): RedactedValue {
139		try {
140			return redactValue(args, 0, new WeakSet<object>());
141		} catch {
142			return "[unavailable]";
143		}
144	}
145	
146	/**
147	 * Write a single bounded structured debug record to stderr without throwing.
148	 */
149	export function debugLog(event: string, data: DebugData): void {
150		if (!isDebugEnabled()) {
151			return;
152		}
153	
154		try {
155			const record = JSON.stringify({ event, ...data });
156			const output =
157				record.length <= MAX_DEBUG_RECORD_LENGTH
158					? record
159					: JSON.stringify({ event, truncated: true });
160			process.stderr.write(`${DEBUG_PREFIX}${output}\n`);
161		} catch {
162			// Diagnostics must never affect tool or API behavior.
163		}
164	}

